# ---- high resolution report figures ----
def architecture():
    fig,ax=plt.subplots(figsize=(12,7)); ax.set_xlim(0,12); ax.set_ylim(0,7); ax.axis('off')
    boxes=[(4.0,5.7,4,0.8,'Users: Administrator · Student'),(4,4.25,4,.8,'Flask Web UI · REST API · Demo Predictor'),(4,2.8,4,.8,'Routes / Controllers · Validation · CSRF'),(4,1.35,4,.8,'Services: ML inference · Alerts · Chatbot'),(4,.0,4,.8,'SQLAlchemy ORM · SQLite Demo / MySQL'),(9,1.55,2,1,'Trained ML Artifacts\nScaler + Classifiers'),(.5,1.55,2,1,'Report / Analytics\nExports & Metrics')]
    for x,y,w,h,t in boxes:
        ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.03,rounding_size=.12',fc='#e9efff' if x==4 else '#e9f8f1',ec='#4857a5',lw=1.6)); ax.text(x+w/2,y+h/2,t,ha='center',va='center',fontsize=10,weight='bold')
    for y1,y2 in [(5.7,5.05),(4.25,3.6),(2.8,2.15),(1.35,.8)]: ax.add_patch(FancyArrowPatch((6,y1),(6,y2),arrowstyle='-|>',mutation_scale=15,color='#475569',lw=1.5))
    ax.add_patch(FancyArrowPatch((8,1.75),(9,2),arrowstyle='<->',mutation_scale=14,color='#475569')); ax.add_patch(FancyArrowPatch((4,1.75),(2.5,2),arrowstyle='<->',mutation_scale=14,color='#475569'))
    fig.tight_layout(); fig.savefig(AS/'system_architecture.png',dpi=300,bbox_inches='tight'); plt.close(fig)

def flow():
    fig,ax=plt.subplots(figsize=(8,10)); ax.set_xlim(0,10); ax.set_ylim(0,12); ax.axis('off')
    items=[('Start / user selects student',10.5),('Validate input ranges & required fields',8.8),('Build ordered 11-feature vector',7.1),('Scale features with fitted StandardScaler',5.4),('Classifier predicts class + probabilities',3.7),('Store prediction audit log',2.0),('Display result, explanations & guidance',.3)]
    for i,(text,y) in enumerate(items):
        ax.add_patch(FancyBboxPatch((2,y),6,.72,boxstyle='round,pad=.05,rounding_size=.15',fc='#eef2ff',ec='#4f46e5',lw=1.5)); ax.text(5,y+.36,text,ha='center',va='center',fontsize=10)
        if i<len(items)-1: ax.add_patch(FancyArrowPatch((5,y),(5,items[i+1][1]+.73),arrowstyle='-|>',mutation_scale=14,color='#64748b'))
    fig.tight_layout(); fig.savefig(AS/'prediction_flow.png',dpi=300,bbox_inches='tight'); plt.close(fig)

def uml():
    fig,ax=plt.subplots(figsize=(11,7)); ax.set_xlim(0,11); ax.set_ylim(0,7); ax.axis('off')
    entities=[(.4,4.5,3,1.7,'Admin','id (PK)\nusername · email\npassword_hash'),(4,4.5,3.4,1.7,'Student','id (PK) · student_id (UQ)\nname · department · semester\nmarks · attendance · habits'),(8,4.5,2.7,1.7,'StudentAuth','id (PK) · student_id (FK)\nusername · password_hash\nactive · last_login'),(4,1,3.4,1.7,'PredictionLog','id (PK) · student_id (FK)\nresult · pass/fail probability\nmodel/version · timestamp')]
    for x,y,w,h,title,body in entities:
        ax.add_patch(plt.Rectangle((x,y),w,h,fc='#fff',ec='#334155',lw=1.6)); ax.add_patch(plt.Rectangle((x,y+h-.42),w,.42,fc='#e0e7ff',ec='#334155')); ax.text(x+w/2,y+h-.21,title,ha='center',va='center',weight='bold'); ax.text(x+.12,y+h-.58,body,va='top',fontsize=9,linespacing=1.4)
    ax.plot([7.4,8],[5.1,5.1],color='#334155'); ax.text(7.6,5.25,'1 — 1',fontsize=9)
    ax.plot([5.7,5.7],[4.5,2.7],color='#334155'); ax.text(5.8,3.45,'1 — *',fontsize=9)
    fig.tight_layout(); fig.savefig(AS/'data_model.png',dpi=300,bbox_inches='tight'); plt.close(fig)

def metrics_plot():
    names=['Logistic Regression','SVM (RBF)','Gradient Boosting','Random Forest']; acc=[83.5,84.75,83.5,83.0]; auc=[.9082,.8978,.8967,.8866]
    fig,ax=plt.subplots(figsize=(10,5.6)); x=range(len(names)); ax.bar([i-.18 for i in x],acc,width=.36,label='Accuracy (%)',color='#4f46e5'); ax.set_ylabel('Accuracy (%)'); ax.set_ylim(75,90); ax.set_xticks(list(x),names,rotation=12,ha='right'); ax.grid(axis='y',alpha=.25); ax2=ax.twinx(); ax2.plot(list(x),auc,color='#f97316',marker='o',lw=2.5,label='ROC-AUC'); ax2.set_ylim(.84,.93); ax2.set_ylabel('ROC-AUC'); ax.legend(loc='upper left'); ax2.legend(loc='upper right'); fig.tight_layout(); fig.savefig(AS/'model_metrics.png',dpi=300,bbox_inches='tight'); plt.close(fig)

